#!/usr/bin/env bash
# {{NAME}} — generated by TERMy ({{LANG}})
set -euo pipefail

factorial() {
    local n="$1" f=1 i
    if (( n < 0 )); then
        printf >&2 'Error: factorial is undefined for negative numbers\n'
        return 1
    fi
    for ((i = 2; i <= n; i++)); do f=$((f * i)); done
    printf '%s! = %s\n' "$n" "$f"
}

factorial {{N}}